sys_script_include.script:
var PortalAccessTracker = Class.create();
PortalAccessTracker.prototype = {
    initialize: function() {
    },

	 getAnonymousAccesses: function(anonId) {
        var result = [];
        var gr = new GlideRecord('x_sded9_portal_t_0_acessos_do_portal');
        gr.addQuery('u_anonimo_id', anonId);
        gr.orderByDesc('u_hora_do_acesso');
        gr.setLimit(5);
        gr.query();
        while (gr.next()) {
            result.push({
                page_id: gr.u_pagina_url.toString(),
                time: gr.u_hora_do_acesso.getDisplayValue()
            });
        }
        return result;
    },

    type: 'PortalAccessTracker'
};
